    // Determine whether to use EXISTS-style based on strategy and operator.
    // innerJoin + NOT IN falls back to NOT EXISTS since there is no direct INNER JOIN equivalent.
    const tvpParam = buildParameterName(paramName);
    const isExistsStyle = operatorStrategy === 'exists' || (operatorStrategy === 'innerJoin' && operator === 'NOT IN');
    if (operatorStrategy === 'innerJoin' && operator === 'IN') {
        statement = `INNER JOIN ${tvpParam} AS ${tvpAlias} ON ${fieldName} = ${tvpAlias}.${tvpColumnName}`;
    } else if (isExistsStyle) {
        const existsKeyword = operator === 'NOT IN' ? 'NOT EXISTS' : 'EXISTS';
        statement = `${existsKeyword} (SELECT 1 FROM ${tvpParam} AS ${tvpAlias} WHERE ${fieldName} = ${tvpAlias}.${tvpColumnName})`;
    } else {
        // Default to IN/NOT IN operator
        statement = `${fieldName} ${operator} (SELECT ${tvpColumnName} FROM ${tvpParam})`;
    }

    return { paramNames: [paramName], values: [tvp], statement, alias: tvpAlias };
}

